47:  * whole-source purge target, three segments above `userBuiltMarketplaceDir`. Named once so
48:  * the version-scoped path and the root holding every version cannot drift apart. */
49: export function userBuiltCacheRoot(userConfigDir: string): string {
50:   return join(userConfigDir, "cache", "built");
51: }
