53: /** The CLI version sits before the marketplace name, so purging one version is a single
54:  * `rm -rf` and two projects on two CLI versions never resolve to the same directory — what
55:  * keeps a second project from silently repointing a host away from the first. */
56: export function userBuiltMarketplaceDir(
57:   userConfigDir: string,
58:   cliVersion: string,
59:   marketplaceName: string,
60:   target: string
61: ): string {
