78: export function parseUserBuiltMarketplaceDir(
79:   userConfigDir: string,
80:   path: string,
81:   platform: string = process.platform
82: ): UserBuiltMarketplaceLocation | undefined {
83:   const segments = segmentsUnder(userBuiltCacheRoot(userConfigDir), path, platform);
84:   if (segments === undefined || segments.length !== 3) return undefined;
85:   const [version, marketplaceName, target] = segments;
86:   return { version, marketplaceName, target };
87: }
