90: export interface BuiltMarketplaceLocation {
91:   readonly marketplaceName: string;
92:   readonly target: string;
93: }
94: 
95: /** The inverse of `builtMarketplaceDir`, decided from the path's own segments the way
96:  * `parseUserBuiltMarketplaceDir` decides the user-scope shape. */
97: export function parseBuiltMarketplaceDir(
98:   projectRoot: string,
99:   path: string,
100:   platform: string = process.platform
101: ): BuiltMarketplaceLocation | undefined {
102:   const segments = segmentsUnder(join(projectRoot, BUILT_CACHE_SUBDIR), path, platform);
103:   if (segments === undefined || segments.length !== 2) return undefined;
104:   const [marketplaceName, target] = segments;
105:   return { marketplaceName, target };
106: }
107: 
108: /** `builtMarketplaceDir`'s own shape plus the project root that produced it — the root
109:  * `parseBuiltMarketplaceDir` has to be handed and this one exists to discover. */
110: export interface AnyProjectBuiltMarketplaceLocation extends BuiltMarketplaceLocation {
111:   readonly projectRoot: string;
112: }
113: 
114: /** Matched segment by segment, never by index arithmetic over a case-folded string: win32
115:  * folding need not preserve length. `projectRoot` is rejoined with `platform`'s own separator,
116:  * since every other writer of `references.json` records a backslash `realpath` on win32 and
117:  * `samePathSegment` compares spelling. */
118: export function parseBuiltMarketplaceDirAtAnyRoot(
119:   path: string,
120:   platform: string = process.platform
121: ): AnyProjectBuiltMarketplaceLocation | undefined {
122:   const segments = stripTrailingSeparator(path.replace(/\\/g, "/")).split("/");
123:   const marker = BUILT_CACHE_SUBDIR.replace(/\\/g, "/").split("/");
124:   const markerStart = segments.length - marker.length - 2;
125:   if (markerStart < 1) return undefined;
126:   const candidateMarker = segments.slice(markerStart, markerStart + marker.length);
127:   const markerMatches = candidateMarker.every(
128:     (segment, index) =>
129:       marker[index] !== undefined && samePathSegment(segment, marker[index], platform)
130:   );
131:   if (!markerMatches) return undefined;
132:   const projectRoot = segments.slice(0, markerStart).join(platform === "win32" ? "\\" : "/");
133:   if (projectRoot.length === 0) return undefined;
134:   const [marketplaceName, target] = segments.slice(markerStart + marker.length);
135:   if (marketplaceName === undefined || target === undefined) return undefined;
136:   return { projectRoot, marketplaceName, target };
137: }
138: 
139: /** The path segments of `path` past `base`, `undefined` when `path` does not sit under
140:  * `base`. Compares spelling — folded by `platform` for the containment test only, so the
141:  * segments returned keep their original casing — and resolves neither side. A trailing
142:  * separator on `base` is tolerated. */
143: function segmentsUnder(base: string, path: string, platform: string): string[] | undefined {
144:   const normalizedBase = stripTrailingSeparator(base.replace(/\\/g, "/"));
145:   const normalizedPath = stripTrailingSeparator(path.replace(/\\/g, "/"));
146:   const compareBase = foldCase(normalizedBase, platform);
147:   const comparePath = foldCase(normalizedPath, platform);
148:   if (!comparePath.startsWith(`${compareBase}/`)) return undefined;
149:   const remainder = normalizedPath.slice(normalizedBase.length + 1);
150:   if (remainder.length === 0) return undefined;
151:   return remainder.split("/");
152: }
153: 
154: function stripTrailingSeparator(p: string): string {
155:   return p.length > 1 && p.endsWith("/") ? p.slice(0, -1) : p;
156: }
157: 
158: function foldCase(p: string, platform: string): string {
159:   return platform === "win32" ? p.toLowerCase() : p;
160: }
161: 
162: /** Whether two path segments name the same thing, folded the way a case-insensitive
163:  * filesystem would: identical spelling everywhere but win32, where the comparison ignores
164:  * case. `platform` is a parameter, never `process.platform` read inline, so a test can
165:  * exercise the win32 branch on any OS. */
166: export function samePathSegment(
167:   a: string,
168:   b: string,
169:   platform: string = process.platform
170: ): boolean {
171:   return platform === "win32" ? a.toLowerCase() === b.toLowerCase() : a === b;
172: }
173: 
174: /** `roots` with every `samePathSegment` duplicate collapsed away, the first spelling kept.
175:  * A plain `Set` compares by exact string equality, so on win32 two entries differing only
176:  * in case — one directory the filesystem never tells apart — would survive as two. */
177: export function dedupePathSegments(
178:   roots: readonly string[],
179:   platform: string = process.platform
180: ): string[] {
181:   const deduped: string[] = [];
182:   for (const root of roots) {
183:     if (!deduped.some((seen) => samePathSegment(seen, root, platform))) deduped.push(root);
184:   }
185:   return deduped;
186: }
187: 
188: // One directory is the other, or contains it — separators normalised, so nesting is
189: // recognised on Windows too. Both sides are expected already resolved: this compares
190: // spelling, it does not resolve.
191: export function pathContainsOrEquals(outer: string, inner: string): boolean {
192:   const normalizedOuter = outer.replace(/\\/g, "/");
193:   const normalizedInner = inner.replace(/\\/g, "/");
194:   return normalizedOuter === normalizedInner || normalizedInner.startsWith(`${normalizedOuter}/`);
195: }
196: 
197: /** Whether two paths name the same directory: separators normalised, and case folded the way
198:  * a case-insensitive filesystem would — on win32 only, where a backslash separates and case
199:  * does not count. Elsewhere a backslash is an ordinary character in a name. Both sides are
200:  * expected already resolved — this
201:  * compares spelling, it does not resolve. A `realpath` answer and a path a host stored name
202:  * the same directory in two spellings on Windows, and `===` calls them different. */
203: export function samePath(a: string, b: string, platform: string = process.platform): boolean {
204:   if (platform !== "win32") return a === b;
205:   const folded = (p: string): string => p.replace(/\\/g, "/").toLowerCase();
206:   return folded(a) === folded(b);
207: }
208: 
209: /** Either direction: neither may sit inside the other. */
210: export function pathsOverlap(a: string, b: string): boolean {
211:   return pathContainsOrEquals(a, b) || pathContainsOrEquals(b, a);
212: }
213: 
214: /** Where the user-scope manifest lives: directly under `userConfigDir()`, never nested in an
215:  * `.aidd/` segment — there is no project to hold one, and `marketplaces.json` and
216:  * `references.json` sit at that same root already. */
217: export function userManifestPath(userConfigDir: string): string {
218:   return join(userConfigDir, MANIFEST_FILENAME);
219: }
220: 
221: /** The manifest's filename, named once because `telemetry-evidence-adapter.ts` and
222:  * `manifest-repository-adapter.ts` both open that file and `aidd telemetry check` prints a
223:  * row from each: two literals would let a rename make those rows contradict each other. */
224: export const MANIFEST_FILENAME = "manifest.json";
225: 
226: /**
227:  * `target` relative to `base`, spelled with forward slashes whatever the platform — the form
228:  * every path this CLI records for another machine to read takes (a manifest's
229:  * `files[].relativePath`, a snapshot key, a plugin ref), so a tree written on Windows and
230:  * read on Linux names the same file.
231:  */
232: export function posixRelative(
233:   base: string,
234:   target: string,
235:   platform: NodeJS.Platform = process.platform
236: ): string {
237:   const impl = platform === "win32" ? win32 : posix;
238:   return impl.relative(base, target).split(impl.sep).join("/");
239: }

