"""Spike 'survie des choix humains d'annees' — H1.

Empreinte d'ecriture de TOUT le depot : qui ecrit, tronque ou efface
quel fichier (analyse AST, pas grep). Sortie : tableau des operations
d'ecriture/suppression, avec le nom de fichier resolu quand il est statique.

Jetable : n'ecrit rien dans le depot.
"""
import ast
import os
import sys

REPO = '/home/giak/projects/aidd-device-work/2026-10-22-092005-spike-annees/terrain'

COLLECT_CACHES = {
    'year_cache.jsonl', 'discogs_cache.jsonl', 'itunes_cache.jsonl',
    'discogs_reform_cache.jsonl', 'discogs_reform2_cache.jsonl',
    'youtube_topic_cache.jsonl',
}
REVIEW_FILES = {'year_review.json', 'year_audit_review.json'}
WRITE_MODES = {'w', 'a', 'x', '+'}


def const_map(tree):
    """Noms de module -> nom de fichier litteral (join(..., 'lit') ou str)."""
    out = {}
    for node in tree.body:
        if not isinstance(node, ast.Assign) or len(node.targets) != 1:
            continue
        if not isinstance(node.targets[0], ast.Name):
            continue
        name, val = node.targets[0].id, node.value
        if isinstance(val, ast.Constant) and isinstance(val.value, str):
            out[name] = val.value
        elif isinstance(val, ast.Call) and isinstance(val.func, ast.Attribute) \
                and val.func.attr == 'join':
            lits = [a.value for a in val.args
                    if isinstance(a, ast.Constant) and isinstance(a.value, str)]
            if lits:
                out[name] = lits[-1]
    return out


def resolve(expr, consts):
    """(nom de fichier resolu ou None, texte source)."""
    if expr is None:
        return None, ''
    if isinstance(expr, ast.Constant) and isinstance(expr.value, str):
        return expr.value, ast.unparse(expr)
    if isinstance(expr, ast.Name) and expr.id in consts:
        return consts[expr.id], ast.unparse(expr)
    try:
        return None, ast.unparse(expr)
    except Exception:
        return None, '<expr>'


def scan(path):
    try:
        src = open(path, encoding='utf-8').read()
    except (OSError, UnicodeDecodeError):
        return []
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return []
    consts = const_map(tree)
    ops = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        f = node.func
        op, expr = None, None
        if isinstance(f, ast.Name) and f.id == 'open':
            if len(node.args) >= 2 and isinstance(node.args[1], ast.Constant) \
                    and node.args[1].value in WRITE_MODES:
                op, expr = 'open(%s)' % node.args[1].value, node.args[0]
            else:
                op, expr = 'open(read)', node.args[0]
        elif isinstance(f, ast.Name) and f.id == 'save_json':
            op, expr = 'save_json', node.args[0] if node.args else None
        elif isinstance(f, ast.Attribute) and f.attr in (
                'remove', 'unlink', 'rmtree', 'truncate', 'rename', 'replace',
                'write_text', 'write_bytes', 'unlink'):
            op = f.attr
            if f.attr in ('write_text', 'write_bytes'):
                expr = f.value
            else:
                expr = node.args[0] if node.args else None
        if op is None:
            continue
        fname, text = resolve(expr, consts)
        base = os.path.basename(fname) if fname else None
        ops.append({
            'file': os.path.relpath(path, REPO),
            'line': node.lineno,
            'op': op,
            'target_expr': text,
            'filename': base,
            'resolved': fname,
        })
    return ops


def main():
    all_ops = []
    for root, dirs, files in os.walk(REPO):
        dirs[:] = [d for d in dirs if d not in
                   ('.git', 'venv', 'node_modules', '__pycache__', 'static/dist')]
        for f in files:
            if f.endswith('.py'):
                all_ops.extend(scan(os.path.join(root, f)))

    def show(title, pred):
        rows = [o for o in all_ops if pred(o)]
        print('\n== %s (%d) ==' % (title, len(rows)))
        for o in sorted(rows, key=lambda x: (x['file'], x['line'])):
            tgt = o['filename'] or o['target_expr']
            print('  %-42s:%-5s %-12s -> %s' %
                  (o['file'], o['line'], o['op'], tgt))

    show('ECRITURE/SUPPRESSION viseant un FICHIER DE REVUE',
         lambda o: o['filename'] in REVIEW_FILES)
    show('ECRITURE/SUPPRESSION viseant un CACHE DE COLLECTE',
         lambda o: o['filename'] in COLLECT_CACHES)
    show('SUPPRESSION de tout fichier (le vrai risque de perte)',
         lambda o: o['op'] in ('remove', 'unlink', 'rmtree', 'truncate'))
    show('TOUTES les ecritures de caches de collecte (mode inclus)',
         lambda o: o['filename'] in COLLECT_CACHES and o['op'] != 'open(read)')

    print('\n== fichier de revue : qui le LIT ? ==')
    for o in sorted(all_ops, key=lambda x: (x['file'], x['line'])):
        if o['filename'] in REVIEW_FILES and o['op'] == 'open(read)':
            print('  %-42s:%-5s %s' % (o['file'], o['line'], o['target_expr']))
    return 0


if __name__ == '__main__':
    sys.exit(main())

